DELETE FROM public.treinos_ciclo
WHERE ciclo_id = 'aguas-abertas' AND id NOT IN ('aa_d01_intermediario', 'aa_d01_avancado', 'aa_d02_intermediario', 'aa_d02_avancado', 'aa_d03_intermediario', 'aa_d03_avancado', 'aa_d04_intermediario', 'aa_d04_avancado', 'aa_d05_intermediario', 'aa_d05_avancado', 'aa_d06_intermediario', 'aa_d06_avancado', 'aa_d07_intermediario', 'aa_d07_avancado', 'aa_d08_intermediario', 'aa_d08_avancado', 'aa_d09_intermediario', 'aa_d09_avancado', 'aa_d10_intermediario', 'aa_d10_avancado', 'aa_d11_intermediario', 'aa_d11_avancado', 'aa_d12_intermediario', 'aa_d12_avancado', 'aa_d13_intermediario', 'aa_d13_avancado', 'aa_d14_intermediario', 'aa_d14_avancado', 'aa_d15_intermediario', 'aa_d15_avancado', 'aa_d16_intermediario', 'aa_d16_avancado', 'aa_d17_intermediario', 'aa_d17_avancado', 'aa_d18_intermediario', 'aa_d18_avancado', 'aa_d19_intermediario', 'aa_d19_avancado', 'aa_d20_intermediario', 'aa_d20_avancado', 'aa_d21_intermediario', 'aa_d21_avancado', 'aa_d22_intermediario', 'aa_d22_avancado', 'aa_d23_intermediario', 'aa_d23_avancado', 'aa_d24_intermediario', 'aa_d24_avancado', 'aa_d25_intermediario', 'aa_d25_avancado', 'aa_d26_intermediario', 'aa_d26_avancado', 'aa_d27_intermediario', 'aa_d27_avancado', 'aa_d28_intermediario', 'aa_d28_avancado');

-- Conferência: cada dia com Condicionamento e Aperfeiçoamento, com objetivo e
-- zona, e o treino de piscina de hoje continua vindo do ciclo de piscina.
DO $conferencia$
DECLARE
  faltando INT;
  sem_metodo INT;
  modo_de_hoje TEXT;
BEGIN
  SELECT count(*) INTO faltando
  FROM public.ciclos_treino c
  CROSS JOIN generate_series(1, c.dias) AS d(dia)
  CROSS JOIN (VALUES ('INTERMEDIARIO'), ('AVANCADO')) AS n(level)
  LEFT JOIN public.treinos_ciclo tc
    ON tc.ciclo_id = c.id AND tc.ciclo_dia = d.dia AND tc.level = n.level
  WHERE c.id = 'aguas-abertas' AND tc.id IS NULL;

  SELECT count(*) INTO sem_metodo
  FROM public.treinos_ciclo
  WHERE ciclo_id = 'aguas-abertas' AND (objetivo IS NULL OR zona IS NULL);

  SELECT c.modo INTO modo_de_hoje
  FROM public.treinos_sugeridos(p_level => 'INTERMEDIARIO') s
  JOIN public.ciclos_treino c ON c.id = s.ciclo_id;

  IF faltando > 0 OR sem_metodo > 0 OR modo_de_hoje IS DISTINCT FROM 'piscina' THEN
    RAISE EXCEPTION 'Ciclo incompleto (% faltando, % sem objetivo/zona) ou treino de piscina trocado (%). Nada foi gravado.',
      faltando, sem_metodo, modo_de_hoje;
  END IF;
END
$conferencia$;

COMMIT;
